namespace sv_2f263466ff9049219785c3ed0be13537.Services;

/// <summary>
/// Scoped (per-circuit) service that tracks low-stock alert counts and
/// notifies all subscribed components when new data arrives.
/// </summary>
public class InventoryAlertService
{
    private static readonly Random _random = new();

    public int CurrentLowStockCount { get; private set; }

    /// <summary>Raised after alert data is refreshed so every subscriber updates.</summary>
    public event Func<Task>? OnAlertDataChanged;

    /// <summary>Simulates a database query returning low-stock item count.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate latency-free DB call; return random 0–15.
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Fetches new data for the given warehouse and broadcasts the result
    /// to every subscribed component.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        CurrentLowStockCount = await GetLowStockCountAsync(warehouseId);

        if (OnAlertDataChanged is not null)
            await OnAlertDataChanged.Invoke();
    }
}

