@page "/dashboard"
@using sv_2f263466ff9049219785c3ed0be13537.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IAsyncDisposable

<PageTitle>Dashboard — @WarehouseState.CurrentWarehouse.Name</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">@WarehouseState.CurrentWarehouse.Name</h5>
        <p class="card-text text-muted">ID: @WarehouseState.CurrentWarehouse.Id</p>
    </div>
</div>

<div class="row g-4">
    <div class="col-md-4">
        <div class="card text-bg-@(AlertService.CurrentLowStockCount > 5 ? "danger" : AlertService.CurrentLowStockCount > 0 ? "warning" : "success")">
            <div class="card-body text-center">
                <h2 class="display-4">@AlertService.CurrentLowStockCount</h2>
                <p class="mb-0">Low-Stock Alerts</p>
            </div>
        </div>
    </div>

    <div class="col-md-8">
        <div class="card">
            <div class="card-header">Polling Status</div>
            <div class="card-body">
                <p>
                    Polling every <strong>10 seconds</strong> for warehouse
                    <strong>@WarehouseState.CurrentWarehouse.Name</strong>.
                </p>
                <p class="text-muted mb-0">
                    Last refresh: @_lastRefresh?.ToString("HH:mm:ss") ?? "—"
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private DateTime? _lastRefresh;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleWarehouseChanged;
        AlertService.OnAlertDataChanged += HandleAlertChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await StartPollingAsync();
        }
    }

    private async Task HandleWarehouseChanged()
    {
        // Restart polling for the new warehouse immediately.
        StopPolling();
        await StartPollingAsync();
        await InvokeAsync(StateHasChanged);
    }

    private async Task HandleAlertChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    private async Task StartPollingAsync()
    {
        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        // Initial fetch
        await AlertService.RefreshAsync(WarehouseState.CurrentWarehouse.Id);
        _lastRefresh = DateTime.Now;

        _ = Task.Run(async () =>
        {
            using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            try
            {
                while (await timer.WaitForNextTickAsync(token))
                {
                    await AlertService.RefreshAsync(WarehouseState.CurrentWarehouse.Id);
                    _lastRefresh = DateTime.Now;
                }
            }
            catch (OperationCanceledException) { }
        }, token);
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    public ValueTask DisposeAsync()
    {
        WarehouseState.OnChange -= HandleWarehouseChanged;
        AlertService.OnAlertDataChanged -= HandleAlertChanged;
        StopPolling();
        return ValueTask.CompletedTask;
    }
}

